"""Verify team setup and destructive reset, entirely on localhost."""
from playwright.sync_api import sync_playwright,expect
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(service_workers='block',viewport={'width':390,'height':844});t=ctx.new_page();errors=[];t.on('pageerror',lambda e:errors.append(str(e)))
 t.goto('http://127.0.0.1:8772/');t.locator('#startPlaying').click();expect(t.locator('#groupSetupDialog')).to_be_visible();t.locator('#groupSetupName').fill('De Nachtuilen');t.locator('#groupSetupForm button[type=submit]').click();expect(t.locator('#groupBadge')).to_have_text('De Nachtuilen')
 t.locator('#takePhoto').click();t.locator('#photoPicker').set_input_files(ROOT/'assets/references/grumpy-cat.jpg');t.locator('#savePhoto').click();expect(t.locator('#viewerDialog')).to_be_visible();t.locator('[data-close="viewerDialog"]').click();t.reload();expect(t.locator('#groupSetupDialog')).not_to_be_visible();expect(t.locator('#albumBadge')).to_have_text('1');expect(t.locator('#groupBadge')).to_have_text('De Nachtuilen')
 # Seed old image/team stores too: reset must remove all generations.
 t.evaluate('''async()=>{localStorage.setItem('other-app','keep');sessionStorage.setItem('fotojacht-test','delete');document.cookie='fotojacht-test=delete; path=/';const db=await new Promise((ok,no)=>{const r=indexedDB.open('scouting-fotojacht-pictures',2);r.onsuccess=()=>ok(r.result);r.onerror=no});await new Promise((ok,no)=>{const tx=db.transaction(['images','teams'],'readwrite');tx.objectStore('images').put(new Blob(['legacy']),'recreation:foto-001');tx.objectStore('teams').put({id:'old-team'});tx.oncomplete=ok;tx.onerror=no});db.close()}''')
 t.locator('[data-page="album"]').click();t.locator('#resetGame').click();expect(t.locator('#resetDialog')).to_contain_text('Download eerst');t.locator('[data-close="resetDialog"]').click();expect(t.locator('#albumBadge')).to_have_text('1')
 t.locator('#resetGame').click();t.locator('#confirmReset').click();expect(t.locator('#tutorialDialog')).to_be_visible();expect(t.locator('#albumBadge')).to_have_text('0');assert t.evaluate("localStorage.getItem('other-app')")=='keep';assert t.evaluate("sessionStorage.getItem('fotojacht-test')")==None;assert 'fotojacht-test' not in t.evaluate('document.cookie')
 counts=t.evaluate('''async()=>{const db=await new Promise(ok=>{const r=indexedDB.open('scouting-fotojacht-pictures',2);r.onsuccess=()=>ok(r.result)});const counts=await Promise.all([...db.objectStoreNames].map(s=>new Promise(ok=>{const r=db.transaction(s).objectStore(s).count();r.onsuccess=()=>ok(r.result)})));db.close();return counts}''');assert all(n==0 for n in counts),counts
 t.locator('#startPlaying').click();t.locator('#skipGroupName').click();expect(t.locator('#groupBadge')).to_have_text('Onze groep');assert not errors,errors
 t.screenshot(path='/tmp/fotojacht-simplified-mobile.png');b.close();print('PASS: intro → team name, persistence, reset cancellation, reset clears new/legacy photos/teams/preferences/session/cookies and restarts intro; unrelated app data retained.')
